import { afterEach, beforeEach } from "vitest";
import { addLeadingZeros } from "../addLeadingZeros/index.js";
import { setDefaultOptions } from "../defaultOptions/index.js";
import sinon from "sinon";

export function assertType<Type>(_value: Type) {}

export namespace assertType {
  export type Equal<T, U> =
    Exclude<T, U> extends never
      ? Exclude<U, T> extends never
        ? true
        : false
      : false;
}

export function resetDefaultOptions(): void {
  setDefaultOptions({});
}

// This makes sure we create the consistent offsets across timezones, no matter where these tests are ran.
export function generateOffset(originalDate: Date) {
  // Add the timezone.
  let offset = "";
  const tzOffset = originalDate.getTimezoneOffset();

  if (tzOffset !== 0) {
    const absoluteOffset = Math.abs(tzOffset);
    const hourOffset = addLeadingZeros(Math.trunc(absoluteOffset / 60), 2);
    const minuteOffset = addLeadingZeros(absoluteOffset % 60, 2);
    // If less than 0, the sign is +, because it is ahead of time.
    const sign = tzOffset < 0 ? "+" : "-";

    offset = `${sign}${hourOffset}:${minuteOffset}`;
  } else {
    offset = "Z";
  }

  return offset;
}

export function fakeDate(date: number | Date) {
  let clock: sinon.SinonFakeTimers | undefined;

  function fakeNow(date: number | Date) {
    clock?.restore();
    clock = sinon.useFakeTimers(+date);
  }

  beforeEach(() => {
    fakeNow(+date);
  });

  afterEach(() => {
    clock?.restore();
    clock = undefined;
  });

  return { fakeNow };
}

export function promiseQueue<Type>(
  promises: Array<() => Promise<Type>>,
  max: number,
): Promise<Type[]> {
  const queue: Array<() => void> = [];

  const all = Promise.all<Type>(
    new Array(promises.length).fill(null).map((_, index) => {
      const promise = new Promise<void>((resolve) => {
        queue[index] = () => {
          // Trigger the queue promise
          resolve();
          // Return it, so the worker function can wait for
          return promise;
        };
      }).then(() => promises[index]());
      return promise;
    }),
  );

  async function next() {
    const promise = queue.shift();
    if (!promise) return;
    await promise();
    return next();
  }

  // Create the worker functions
  Promise.all(new Array(max).fill(null).map(() => next()));

  return all;
}

import { $ } from "bun";
import { availableParallelism } from "node:os";
import { promiseQueue } from "./queue.js";

export async function testTimeZone(timeZone: string) {
  try {
    await $`TZ=${timeZone} bun test ./src/**/test.ts`.quiet();
  } catch (err: any) {
    console.log(err.stderr.toString());
    console.log(`⛔ Tests for the time zone ${timeZone}`);
    process.exit(err.exitCode);
  }

  console.log(`✅ Tests for the time zone ${timeZone}`);
}

export function testTimeZones(timeZones: string[]) {
  return promiseQueue(
    timeZones.map((timeZone) => () => testTimeZone(timeZone)),
    availableParallelism(),
  );
}

